const e=JSON.parse(`[{"id":1,"category":"nmap","difficulty":"easy","codeSnippet":"nmap -sS 10.0.0.5","question":{"en":"What kind of scan does the -sS flag perform?","ar":"أي نوع من الفحص يقوم به الخيار sS-؟"},"options":["TCP SYN (stealth) scan","UDP datagram port scan","Full TCP connect scan","ICMP host ping sweep"],"answer":"TCP SYN (stealth) scan","explanation":{"en":"-sS sends SYN packets without completing the handshake — a fast, stealthy scan.","ar":"يرسل sS- حزم SYN دون إكمال المصافحة، وهو فحص سريع وخفي."}},{"id":2,"category":"nmap","difficulty":"easy","codeSnippet":"nmap -sV 10.0.0.5","question":{"en":"What does the -sV flag enable?","ar":"ماذا يُفعّل الخيار sV-؟"},"options":["Service/version detection","Operating system detection","Automated vulnerability scan","Firewall port-knock probe"],"answer":"Service/version detection","explanation":{"en":"-sV probes open ports to determine the service and version running.","ar":"يفحص sV- المنافذ المفتوحة لتحديد الخدمة وإصدارها."}},{"id":3,"category":"nmap","difficulty":"easy","codeSnippet":"nmap -p- 10.0.0.5","question":{"en":"Which ports does -p- scan?","ar":"أي منافذ يفحصها p--؟"},"options":["All 65535 TCP ports","Only the top 100 ports","UDP ports only","Privileged ports only"],"answer":"All 65535 TCP ports","explanation":{"en":"-p- tells Nmap to scan every TCP port from 1 to 65535.","ar":"يطلب p-- من Nmap فحص كل منفذ TCP من 1 إلى 65535."}},{"id":4,"category":"nmap","difficulty":"medium","codeSnippet":"nmap -O 10.0.0.5","question":{"en":"What does the -O flag do?","ar":"ماذا يفعل الخيار O-؟"},"options":["OS detection","Output to a file","Open ports only","Aggressive timing"],"answer":"OS detection","explanation":{"en":"-O enables operating-system fingerprinting.","ar":"يُفعّل O- بصمة نظام التشغيل."}},{"id":5,"category":"nmap","difficulty":"medium","codeSnippet":"nmap -sU 10.0.0.5","question":{"en":"What does -sU perform?","ar":"ماذا يؤدي sU-؟"},"options":["UDP scan","SYN scan","Slow comprehensive scan","Stealth TCP scan"],"answer":"UDP scan","explanation":{"en":"-sU scans UDP ports.","ar":"يفحص sU- منافذ UDP."}},{"id":6,"category":"nmap","difficulty":"medium","codeSnippet":"nmap -A 10.0.0.5","question":{"en":"What does the -A flag enable?","ar":"ماذا يُفعّل الخيار A-؟"},"options":["OS + version + scripts + traceroute","Anonymous low-and-slow scanning","An ARP-only local network scan","A scan of all UDP ports only"],"answer":"OS + version + scripts + traceroute","explanation":{"en":"-A is aggressive: OS detection, version detection, NSE scripts, and traceroute.","ar":"A- عدواني: كشف النظام والإصدار وسكربتات NSE وتتبّع المسار."}},{"id":7,"category":"nmap","difficulty":"hard","codeSnippet":"nmap --script vuln 10.0.0.5","question":{"en":"What does this command run?","ar":"ماذا يُشغّل هذا الأمر؟"},"options":["NSE vulnerability scripts","A simple SYN scan","A brute-force attack","A packet capture"],"answer":"NSE vulnerability scripts","explanation":{"en":"--script vuln runs the Nmap Scripting Engine's vulnerability-detection scripts.","ar":"يشغّل script vuln-- سكربتات كشف الثغرات في محرك Nmap (NSE)."}},{"id":8,"category":"nmap","difficulty":"easy","codeSnippet":"","question":{"en":"Which tool is the de-facto standard network port scanner?","ar":"ما الأداة المعيارية لفحص منافذ الشبكة؟"},"options":["Nmap","Metasploit","Wireshark","John the Ripper"],"answer":"Nmap","explanation":{"en":"Nmap is the most widely used network discovery and port-scanning tool.","ar":"Nmap هي الأداة الأكثر استخداماً لاكتشاف الشبكات وفحص المنافذ."}},{"id":9,"category":"malware","difficulty":"easy","codeSnippet":"","question":{"en":"Malware that encrypts your files and demands payment is called?","ar":"ما اسم البرمجية الخبيثة التي تشفّر ملفاتك وتطلب فدية؟"},"options":["Ransomware","Network worm","Kernel rootkit","Bundled adware"],"answer":"Ransomware","explanation":{"en":"Ransomware encrypts data and demands a ransom for the decryption key.","ar":"تشفّر برمجيات الفدية البيانات وتطلب فدية مقابل مفتاح فك التشفير."}},{"id":10,"category":"malware","difficulty":"easy","codeSnippet":"","question":{"en":"Self-replicating malware that spreads across networks on its own is a?","ar":"البرمجية الخبيثة ذاتية الانتشار عبر الشبكات بلا تدخل تُسمى؟"},"options":["Worm","Virus","Trojan","Spyware"],"answer":"Worm","explanation":{"en":"A worm spreads independently without needing a host file or user action.","ar":"تنتشر الدودة ذاتياً دون الحاجة لملف مضيف أو تدخل المستخدم."}},{"id":11,"category":"malware","difficulty":"easy","codeSnippet":"","question":{"en":"Malware disguised as legitimate software is a?","ar":"البرمجية الخبيثة المتنكّرة كبرنامج شرعي تُسمى؟"},"options":["Trojan","Worm","Rootkit","Ransomware"],"answer":"Trojan","explanation":{"en":"A Trojan tricks the user into running it by appearing legitimate.","ar":"يخدع حصان طروادة المستخدم لتشغيله بالظهور كبرنامج شرعي."}},{"id":12,"category":"malware","difficulty":"medium","codeSnippet":"","question":{"en":"Malware that hides itself and grants stealthy privileged access is a?","ar":"البرمجية التي تُخفي نفسها وتمنح وصولاً متميزاً خفياً تُسمى؟"},"options":["Rootkit","Adware","Keylogger","Botnet"],"answer":"Rootkit","explanation":{"en":"A rootkit hides deep in the system and maintains privileged, stealthy access.","ar":"يختبئ الـ rootkit عميقاً في النظام ويحافظ على وصول متميز خفي."}},{"id":13,"category":"malware","difficulty":"medium","codeSnippet":"","question":{"en":"Software that secretly records keystrokes to steal credentials is a?","ar":"البرنامج الذي يسجّل ضغطات المفاتيح سراً لسرقة بيانات الدخول هو؟"},"options":["Keylogger","Ransomware","Worm","Rootkit"],"answer":"Keylogger","explanation":{"en":"A keylogger captures keystrokes, often to steal passwords.","ar":"يلتقط الـ keylogger ضغطات المفاتيح، غالباً لسرقة كلمات المرور."}},{"id":14,"category":"malware","difficulty":"medium","codeSnippet":"","question":{"en":"A network of compromised machines remotely controlled by an attacker is a?","ar":"شبكة أجهزة مخترقة يتحكم بها المهاجم عن بُعد تُسمى؟"},"options":["Botnet","Honeypot","DMZ","Sandbox"],"answer":"Botnet","explanation":{"en":"A botnet is a group of infected 'bot' machines under an attacker's control.","ar":"الـ botnet مجموعة أجهزة مصابة (bots) تحت سيطرة المهاجم."}},{"id":15,"category":"malware","difficulty":"medium","codeSnippet":"","question":{"en":"Malware that needs a host program and runs when that program executes is a?","ar":"البرمجية التي تحتاج برنامجاً مضيفاً وتعمل عند تشغيله تُسمى؟"},"options":["Virus","Worm","Trojan","Spyware"],"answer":"Virus","explanation":{"en":"A virus attaches to a host file and runs when the host is executed.","ar":"يرتبط الفيروس بملف مضيف ويعمل عند تشغيل المضيف."}},{"id":16,"category":"malware","difficulty":"hard","codeSnippet":"","question":{"en":"Malicious code that triggers when a specific condition or date is met is a?","ar":"الشيفرة الخبيثة التي تنشط عند تحقق شرط أو تاريخ معيّن تُسمى؟"},"options":["Logic bomb","Network worm","Trojan horse","Kernel rootkit"],"answer":"Logic bomb","explanation":{"en":"A logic bomb lies dormant until its trigger condition is satisfied.","ar":"تظل القنبلة المنطقية خاملة حتى يتحقق شرط تفعيلها."}},{"id":17,"category":"metasploit","difficulty":"easy","codeSnippet":"msfconsole","question":{"en":"msfconsole is the main interface for which framework?","ar":"msfconsole هي الواجهة الرئيسية لأي إطار عمل؟"},"options":["Metasploit Framework","The Nmap port scanner","The Burp Suite proxy","The Wireshark sniffer"],"answer":"Metasploit Framework","explanation":{"en":"msfconsole is the primary command-line interface to the Metasploit Framework.","ar":"msfconsole هي الواجهة الطرفية الأساسية لإطار Metasploit."}},{"id":18,"category":"metasploit","difficulty":"medium","codeSnippet":"use exploit/windows/smb/ms17_010_eternalblue","question":{"en":"Which vulnerability does this Metasploit module target?","ar":"أي ثغرة تستهدفها هذه الوحدة في Metasploit؟"},"options":["SMBv1 (EternalBlue)","OpenSSH remote login","Apache HTTP server","An FTP file service"],"answer":"SMBv1 (EternalBlue)","explanation":{"en":"ms17_010 / EternalBlue exploits a flaw in Microsoft SMBv1.","ar":"تستغل ms17_010 / EternalBlue ثغرة في بروتوكول SMBv1 من مايكروسوفت."}},{"id":19,"category":"metasploit","difficulty":"medium","codeSnippet":"","question":{"en":"In Metasploit, what is a 'payload'?","ar":"في Metasploit، ما هو الـ payload؟"},"options":["Code that runs after a successful exploit","A module that scans for open ports","A firewall traffic-filtering rule","A one-way password hashing method"],"answer":"Code that runs after a successful exploit","explanation":{"en":"The payload is the code executed on the target after the exploit succeeds.","ar":"الـ payload هو الشيفرة التي تُنفَّذ على الهدف بعد نجاح الاستغلال."}},{"id":20,"category":"metasploit","difficulty":"hard","codeSnippet":"","question":{"en":"What is Meterpreter?","ar":"ما هو Meterpreter؟"},"options":["An advanced in-memory Metasploit payload","A fast TCP/UDP network port scanner","An offline password-hash cracking tool","A live network packet sniffer tool"],"answer":"An advanced in-memory Metasploit payload","explanation":{"en":"Meterpreter is a powerful, in-memory Metasploit payload for post-exploitation.","ar":"Meterpreter هو payload قوي يعمل في الذاكرة لمرحلة ما بعد الاستغلال."}},{"id":21,"category":"metasploit","difficulty":"medium","codeSnippet":"set RHOSTS 10.0.0.5","question":{"en":"In Metasploit, what does RHOSTS set?","ar":"في Metasploit، ماذا يضبط RHOSTS؟"},"options":["The target host(s)","The local host","The payload","The port range"],"answer":"The target host(s)","explanation":{"en":"RHOSTS specifies the remote/target host(s); LHOST is your local host.","ar":"يحدد RHOSTS الهدف البعيد، بينما LHOST هو جهازك المحلي."}},{"id":22,"category":"metasploit","difficulty":"hard","codeSnippet":"msfvenom -p windows/meterpreter/reverse_tcp LHOST=10.0.0.2 -f exe","question":{"en":"What is msfvenom used for?","ar":"فيمَ يُستخدم msfvenom؟"},"options":["Generating payloads / shellcode","Scanning networks for open ports","Cracking captured password hashes","Sniffing live network traffic"],"answer":"Generating payloads / shellcode","explanation":{"en":"msfvenom generates and encodes standalone payloads/shellcode.","ar":"يولّد msfvenom ويُرمّز payloads/shellcode مستقلة."}},{"id":23,"category":"tools","difficulty":"easy","codeSnippet":"","question":{"en":"Which tool captures and analyzes network packets with a GUI?","ar":"أي أداة تلتقط وتحلّل حزم الشبكة بواجهة رسومية؟"},"options":["Wireshark","Metasploit","Aircrack","Hydra"],"answer":"Wireshark","explanation":{"en":"Wireshark is the standard GUI packet analyzer.","ar":"Wireshark هي المحلّل الرسومي القياسي للحزم."}},{"id":24,"category":"tools","difficulty":"medium","codeSnippet":"","question":{"en":"Which tool is an intercepting proxy/scanner for web application testing?","ar":"أي أداة تعمل كبروكسي اعتراضي وماسح لاختبار تطبيقات الويب؟"},"options":["Burp Suite","Nmap","Aircrack-ng","John the Ripper"],"answer":"Burp Suite","explanation":{"en":"Burp Suite proxies and manipulates web traffic for security testing.","ar":"يعترض Burp Suite حركة الويب ويعدّلها لأغراض اختبار الأمان."}},{"id":25,"category":"tools","difficulty":"medium","codeSnippet":"sqlmap -u \\"http://site/?id=1\\" --dbs","question":{"en":"What does sqlmap automate?","ar":"ماذا يُؤتمت sqlmap؟"},"options":["SQL injection detection & exploitation","Wireless network password cracking work","Network port scanning and host mapping","Live network packet capture and replay"],"answer":"SQL injection detection & exploitation","explanation":{"en":"sqlmap automatically finds and exploits SQL injection flaws.","ar":"يكتشف sqlmap ثغرات حقن SQL ويستغلها آلياً."}},{"id":26,"category":"tools","difficulty":"medium","codeSnippet":"john --wordlist=rockyou.txt hashes.txt","question":{"en":"What is John the Ripper used for?","ar":"فيمَ يُستخدم John the Ripper؟"},"options":["Cracking password hashes offline","Scanning networks for live hosts","Capturing packets off the wire","Proxying and editing web requests"],"answer":"Cracking password hashes offline","explanation":{"en":"John the Ripper is a popular offline password-hash cracker.","ar":"John the Ripper أداة شهيرة لكسر تجزئات كلمات المرور دون اتصال."}},{"id":27,"category":"tools","difficulty":"medium","codeSnippet":"hydra -l admin -P pass.txt ssh://10.0.0.5","question":{"en":"What does Hydra do?","ar":"ماذا يفعل Hydra؟"},"options":["Online brute-force login attacks","Static application code analysis","Passive network packet sniffing","Disk imaging and forensics work"],"answer":"Online brute-force login attacks","explanation":{"en":"Hydra brute-forces logins across many protocols (SSH, FTP, HTTP...).","ar":"ينفّذ Hydra هجمات تخمين تسجيل الدخول عبر بروتوكولات متعددة."}},{"id":28,"category":"tools","difficulty":"hard","codeSnippet":"","question":{"en":"Which suite assesses Wi-Fi (WEP/WPA) security?","ar":"أي حزمة تُستخدم لتقييم أمان شبكات Wi-Fi؟"},"options":["Aircrack-ng","Burp Suite","Metasploit","sqlmap"],"answer":"Aircrack-ng","explanation":{"en":"Aircrack-ng is a suite for auditing wireless network security.","ar":"Aircrack-ng حزمة لتدقيق أمان الشبكات اللاسلكية."}},{"id":29,"category":"tools","difficulty":"hard","codeSnippet":"hashcat -m 0 hash.txt rockyou.txt","question":{"en":"What is hashcat?","ar":"ما هو hashcat؟"},"options":["A GPU-accelerated password cracker","A fast multi-host port scanner tool","An intercepting web proxy service","A live network packet sniffer tool"],"answer":"A GPU-accelerated password cracker","explanation":{"en":"hashcat is a fast, GPU-based password/hash recovery tool.","ar":"hashcat أداة سريعة لاستعادة كلمات المرور تعتمد على بطاقة الرسوميات."}},{"id":30,"category":"tools","difficulty":"easy","codeSnippet":"","question":{"en":"Which Linux distribution is purpose-built for penetration testing?","ar":"أي توزيعة Linux مُصمّمة خصيصاً لاختبار الاختراق؟"},"options":["Kali Linux","Ubuntu Server","CentOS","Alpine"],"answer":"Kali Linux","explanation":{"en":"Kali Linux ships with hundreds of pre-installed security tools.","ar":"تأتي Kali Linux بمئات أدوات الأمان المثبتة مسبقاً."}},{"id":31,"category":"tools","difficulty":"medium","codeSnippet":"tcpdump -i eth0 port 80","question":{"en":"What does tcpdump do?","ar":"ماذا يفعل tcpdump؟"},"options":["Capture packets from the command line","Crack captured password hashes offline","Scan a target host for open ports","Exploit a vulnerable SMB service"],"answer":"Capture packets from the command line","explanation":{"en":"tcpdump is a CLI packet capture/analysis tool.","ar":"tcpdump أداة طرفية لالتقاط وتحليل الحزم."}},{"id":32,"category":"tools","difficulty":"hard","codeSnippet":"","question":{"en":"Which is an open-source vulnerability scanner (Nessus-like)?","ar":"أيّها ماسح ثغرات مفتوح المصدر (شبيه بـ Nessus)؟"},"options":["OpenVAS","Hydra","John the Ripper","Wireshark"],"answer":"OpenVAS","explanation":{"en":"OpenVAS (Greenbone) is an open-source vulnerability scanner.","ar":"OpenVAS ماسح ثغرات مفتوح المصدر."}},{"id":33,"category":"concepts","difficulty":"easy","codeSnippet":"","question":{"en":"Injecting malicious SQL through user input to manipulate a database is?","ar":"حقن SQL خبيث عبر مدخلات المستخدم للتلاعب بقاعدة البيانات هو؟"},"options":["SQL injection","Reflected XSS","CSRF token theft","SSRF request"],"answer":"SQL injection","explanation":{"en":"SQL injection abuses unsanitized input to alter database queries.","ar":"يستغل حقن SQL المدخلات غير المُنقّاة لتغيير استعلامات قاعدة البيانات."}},{"id":34,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"Injecting client-side scripts into pages viewed by other users is?","ar":"حقن سكربتات تعمل لدى المستخدمين الآخرين في صفحات الويب هو؟"},"options":["Cross-Site Scripting (XSS)","SQL database injection attack","Credential phishing email","Man-in-the-middle attack"],"answer":"Cross-Site Scripting (XSS)","explanation":{"en":"XSS injects scripts that run in other users' browsers.","ar":"يحقن XSS سكربتات تعمل في متصفحات المستخدمين الآخرين."}},{"id":35,"category":"concepts","difficulty":"hard","codeSnippet":"","question":{"en":"Tricking a victim's browser into making unwanted authenticated requests is?","ar":"خداع متصفح الضحية لإرسال طلبات مُصادَق عليها دون رغبته هو؟"},"options":["CSRF","XSS","SQL injection","DoS"],"answer":"CSRF","explanation":{"en":"CSRF abuses a user's existing session to perform actions they didn't intend.","ar":"يستغل CSRF جلسة المستخدم القائمة لتنفيذ أفعال لم يقصدها."}},{"id":36,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"Secretly intercepting communication between two parties is a ... attack?","ar":"اعتراض الاتصال بين طرفين سراً هو هجوم؟"},"options":["Man-in-the-Middle (MITM)","Credential brute forcing","Targeted phishing email","Volumetric DDoS flood"],"answer":"Man-in-the-Middle (MITM)","explanation":{"en":"A MITM attacker sits between two parties and can read/alter traffic.","ar":"يجلس مهاجم MITM بين طرفين ويستطيع قراءة وتعديل الحركة."}},{"id":37,"category":"concepts","difficulty":"easy","codeSnippet":"","question":{"en":"Flooding a service with traffic from many sources to take it offline is?","ar":"إغراق خدمة بحركة من مصادر كثيرة لإسقاطها هو؟"},"options":["DDoS","Phishing","XSS","Privilege escalation"],"answer":"DDoS","explanation":{"en":"A Distributed Denial of Service overwhelms a target from many machines.","ar":"يُغرق هجوم الحرمان الموزّع الهدف من أجهزة كثيرة."}},{"id":38,"category":"concepts","difficulty":"easy","codeSnippet":"","question":{"en":"A deceptive email that tricks users into revealing credentials is?","ar":"بريد خادع يخدع المستخدمين للكشف عن بياناتهم هو؟"},"options":["Phishing","Sniffing","Spoofing","Pivoting"],"answer":"Phishing","explanation":{"en":"Phishing uses deceptive messages to harvest credentials or data.","ar":"يستخدم التصيّد رسائل خادعة لجمع بيانات الاعتماد."}},{"id":39,"category":"concepts","difficulty":"hard","codeSnippet":"","question":{"en":"Which is a SECURE choice for password storage?","ar":"أيّها خيار آمن لتخزين كلمات المرور؟"},"options":["bcrypt","MD5","SHA-1","Base64"],"answer":"bcrypt","explanation":{"en":"bcrypt is a slow, salted password hash; MD5/SHA-1 are weak and Base64 isn't hashing.","ar":"bcrypt تجزئة بطيئة ومملّحة؛ أما MD5/SHA-1 فضعيفتان وBase64 ليست تجزئة."}},{"id":40,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"Giving users only the access they need is the principle of?","ar":"منح المستخدمين الحد الأدنى من الصلاحيات هو مبدأ؟"},"options":["Least privilege","Defense in depth","Zero trust","Fail-safe defaults"],"answer":"Least privilege","explanation":{"en":"Least privilege limits each account to the minimum access required.","ar":"يقصُر مبدأ أقل امتياز كل حساب على الحد الأدنى من الوصول اللازم."}},{"id":41,"category":"nmap","difficulty":"medium","codeSnippet":"nmap -Pn 10.0.0.5","question":{"en":"What does the -Pn flag do?","ar":"ماذا يفعل الخيار Pn-؟"},"options":["Skip host discovery (treat host as online)","Scan every one of the 65,535 TCP ports","Disable all reverse DNS resolution","Send only ICMP echo ping probes first"],"answer":"Skip host discovery (treat host as online)","explanation":{"en":"-Pn skips the ping/host-discovery phase and scans as if the host is up.","ar":"يتخطّى Pn- مرحلة اكتشاف المضيف ويفحص كأنه متصل."}},{"id":42,"category":"nmap","difficulty":"medium","codeSnippet":"nmap -sn 10.0.0.0/24","question":{"en":"What does -sn perform?","ar":"ماذا يؤدي sn-؟"},"options":["Host discovery only (no port scan)","A full all-ports TCP port scan","A UDP datagram-based port scan","Service and version detection"],"answer":"Host discovery only (no port scan)","explanation":{"en":"-sn is a ping sweep: it finds live hosts without scanning ports.","ar":"sn- مسح ping: يكتشف المضيفين الأحياء دون فحص المنافذ."}},{"id":43,"category":"nmap","difficulty":"medium","codeSnippet":"nmap -T4 10.0.0.5","question":{"en":"What does -T4 control?","ar":"ماذا يضبط T4-؟"},"options":["Timing/speed template","Thread count only","Target count","Output format"],"answer":"Timing/speed template","explanation":{"en":"-T0..-T5 set timing templates; -T4 is fast/aggressive.","ar":"تضبط T0..T5- قوالب التوقيت؛ وT4- سريع/عدواني."}},{"id":44,"category":"nmap","difficulty":"easy","codeSnippet":"nmap -F 10.0.0.5","question":{"en":"What does -F do?","ar":"ماذا يفعل F-؟"},"options":["Fast scan (top 100 ports)","Full 65,535-port scan","Force an aggressive scan","Firewall evasion mode"],"answer":"Fast scan (top 100 ports)","explanation":{"en":"-F scans only the 100 most common ports.","ar":"يفحص F- أكثر 100 منفذ شيوعاً فقط."}},{"id":45,"category":"nmap","difficulty":"easy","codeSnippet":"nmap -oN scan.txt 10.0.0.5","question":{"en":"What does -oN do?","ar":"ماذا يفعل oN-؟"},"options":["Save normal output to a file","Scan and show only open ports","Disable all of the scan output","Run the default NSE scripts"],"answer":"Save normal output to a file","explanation":{"en":"-oN writes results in normal format to the given file.","ar":"يكتب oN- النتائج بصيغة عادية إلى الملف المحدد."}},{"id":46,"category":"tools","difficulty":"medium","codeSnippet":"nc -lvnp 4444","question":{"en":"What is netcat (nc) doing here?","ar":"ماذا يفعل netcat هنا؟"},"options":["Listening for a reverse shell","Cracking captured password hashes","Scanning a target host's ports","Sniffing nearby wireless traffic"],"answer":"Listening for a reverse shell","explanation":{"en":"nc -lvnp opens a listener, commonly to catch a reverse shell.","ar":"يفتح nc -lvnp مستمعاً، غالباً لاستقبال reverse shell."}},{"id":47,"category":"tools","difficulty":"medium","codeSnippet":"gobuster dir -u http://site -w words.txt","question":{"en":"What does gobuster do here?","ar":"ماذا يفعل gobuster هنا؟"},"options":["Brute-force directories/files","Crack stored password hashes","Capture live network packets","Exploit a vulnerable SMB share"],"answer":"Brute-force directories/files","explanation":{"en":"gobuster dir brute-forces web paths from a wordlist.","ar":"يخمّن gobuster dir مسارات الويب من قائمة كلمات."}},{"id":48,"category":"tools","difficulty":"medium","codeSnippet":"","question":{"en":"Which tool scans web servers for known vulnerabilities/misconfigurations?","ar":"أي أداة تفحص خوادم الويب بحثاً عن ثغرات وأخطاء إعداد معروفة؟"},"options":["Nikto","Hydra","John the Ripper","Aircrack-ng"],"answer":"Nikto","explanation":{"en":"Nikto scans web servers for thousands of known issues.","ar":"يفحص Nikto خوادم الويب بحثاً عن آلاف المشاكل المعروفة."}},{"id":49,"category":"tools","difficulty":"hard","codeSnippet":"","question":{"en":"Mimikatz is primarily used to?","ar":"فيمَ يُستخدم Mimikatz أساساً؟"},"options":["Extract Windows credentials from memory","Scan a whole network for open ports","Crack wireless Wi-Fi network passwords","Fuzz a web application's inputs"],"answer":"Extract Windows credentials from memory","explanation":{"en":"Mimikatz dumps plaintext passwords, hashes and tickets from memory.","ar":"يستخرج Mimikatz كلمات المرور والتجزئات والتذاكر من الذاكرة."}},{"id":50,"category":"tools","difficulty":"hard","codeSnippet":"","question":{"en":"BloodHound is used to?","ar":"فيمَ يُستخدم BloodHound؟"},"options":["Map Active Directory attack paths","Capture and analyze live packets","Brute-force user account logins","Disassemble compiled binaries"],"answer":"Map Active Directory attack paths","explanation":{"en":"BloodHound graphs AD relationships to find privilege-escalation paths.","ar":"يرسم BloodHound علاقات Active Directory لإيجاد مسارات تصعيد الصلاحيات."}},{"id":51,"category":"tools","difficulty":"hard","codeSnippet":"","question":{"en":"Responder is used to?","ar":"فيمَ يُستخدم Responder؟"},"options":["Poison LLMNR/NBT-NS to capture hashes","Scan a whole subnet for open ports","Crack captured NTLM password hashes","Proxy and modify live web traffic"],"answer":"Poison LLMNR/NBT-NS to capture hashes","explanation":{"en":"Responder spoofs LLMNR/NBT-NS responses to capture NetNTLM hashes.","ar":"يزوّر Responder ردود LLMNR/NBT-NS لالتقاط تجزئات NetNTLM."}},{"id":52,"category":"tools","difficulty":"hard","codeSnippet":"","question":{"en":"Which is a commercial command-and-control / adversary-simulation framework?","ar":"أيّها إطار قيادة وتحكم / محاكاة خصوم تجاري؟"},"options":["Cobalt Strike","Metasploit Pro","PowerShell Empire","Sliver"],"answer":"Cobalt Strike","explanation":{"en":"Cobalt Strike is a commercial C2 and red-team platform.","ar":"Cobalt Strike منصة قيادة وتحكم واختبار أحمر تجارية."}},{"id":53,"category":"tools","difficulty":"medium","codeSnippet":"","question":{"en":"Ghidra and IDA are tools for?","ar":"Ghidra و IDA أدوات لـ؟"},"options":["Reverse engineering / disassembly","Network port scanning and mapping","Live network packet capturing","Offline password-hash cracking"],"answer":"Reverse engineering / disassembly","explanation":{"en":"Ghidra and IDA disassemble/decompile binaries for analysis.","ar":"يفكّك Ghidra و IDA الملفات الثنائية لتحليلها."}},{"id":54,"category":"tools","difficulty":"hard","codeSnippet":"","question":{"en":"Volatility is used for?","ar":"فيمَ يُستخدم Volatility؟"},"options":["Memory (RAM) forensics","Disk image forensics","Network port scanning","Web application fuzzing"],"answer":"Memory (RAM) forensics","explanation":{"en":"Volatility analyzes RAM dumps to investigate compromises.","ar":"يحلّل Volatility صور الذاكرة للتحقيق في الاختراقات."}},{"id":55,"category":"tools","difficulty":"medium","codeSnippet":"","question":{"en":"Which tool enumerates SMB shares and users on Windows?","ar":"أي أداة تعدّد مشاركات ومستخدمي SMB على ويندوز؟"},"options":["enum4linux","hashcat","Aircrack-ng","Volatility"],"answer":"enum4linux","explanation":{"en":"enum4linux enumerates SMB shares, users and policies.","ar":"يعدّد enum4linux مشاركات ومستخدمي وسياسات SMB."}},{"id":56,"category":"tools","difficulty":"medium","codeSnippet":"","question":{"en":"Burp Suite's 'Intruder' is used for?","ar":"فيمَ يُستخدم Intruder في Burp Suite؟"},"options":["Automated/customized request attacks (fuzzing, brute force)","Automated forensic analysis of disk images and file systems","Passive network port scanning and host mapping","Live capture and inspection of raw network packets"],"answer":"Automated/customized request attacks (fuzzing, brute force)","explanation":{"en":"Intruder automates customized HTTP request attacks.","ar":"يؤتمت Intruder هجمات طلبات HTTP المخصّصة."}},{"id":57,"category":"malware","difficulty":"easy","codeSnippet":"","question":{"en":"Malware that secretly collects a user's information/activity is?","ar":"البرمجية التي تجمع معلومات/نشاط المستخدم سراً تُسمى؟"},"options":["Spyware","Adware","Worm","Rootkit"],"answer":"Spyware","explanation":{"en":"Spyware covertly gathers information about the user.","ar":"تجمع برامج التجسس معلومات المستخدم خفية."}},{"id":58,"category":"malware","difficulty":"medium","codeSnippet":"","question":{"en":"Malware that gives an attacker full remote control of a host is a?","ar":"البرمجية التي تمنح المهاجم تحكّماً كاملاً عن بُعد هي؟"},"options":["RAT (Remote Access Trojan)","Intrusive pop-up adware app","A self-spreading network worm","A silent keystroke logger"],"answer":"RAT (Remote Access Trojan)","explanation":{"en":"A RAT gives covert, full remote control of the victim machine.","ar":"يمنح RAT تحكّماً كاملاً خفياً بجهاز الضحية."}},{"id":59,"category":"malware","difficulty":"hard","codeSnippet":"","question":{"en":"Malware that runs entirely in memory, leaving little on disk, is?","ar":"البرمجية التي تعمل في الذاكرة دون أثر يُذكر على القرص هي؟"},"options":["Fileless malware","Macro virus","Boot-sector virus","Adware"],"answer":"Fileless malware","explanation":{"en":"Fileless malware lives in memory to evade file-based detection.","ar":"تعيش البرمجيات عديمة الملفات في الذاكرة لتفادي الكشف."}},{"id":60,"category":"malware","difficulty":"medium","codeSnippet":"","question":{"en":"Malware whose only goal is to destroy data is a?","ar":"البرمجية التي هدفها الوحيد تدمير البيانات هي؟"},"options":["Wiper","Ransomware","Spyware","Adware"],"answer":"Wiper","explanation":{"en":"A wiper irreversibly destroys data (no ransom involved).","ar":"يُدمّر الـ wiper البيانات نهائياً دون فدية."}},{"id":61,"category":"malware","difficulty":"medium","codeSnippet":"","question":{"en":"A small program that downloads and installs other malware is a?","ar":"البرنامج الصغير الذي ينزّل ويثبّت برمجيات أخرى هو؟"},"options":["Dropper","Honeypot","Sandbox","Proxy"],"answer":"Dropper","explanation":{"en":"A dropper delivers and installs additional malware payloads.","ar":"يوصل الـ dropper ويثبّت حمولات خبيثة إضافية."}},{"id":62,"category":"malware","difficulty":"medium","codeSnippet":"","question":{"en":"Hijacking a victim's resources to secretly mine cryptocurrency is?","ar":"اختطاف موارد الضحية لتعدين العملات سراً هو؟"},"options":["Cryptojacking","Phishing","Sniffing","Spoofing"],"answer":"Cryptojacking","explanation":{"en":"Cryptojacking abuses a victim's CPU/GPU to mine cryptocurrency.","ar":"يستغل Cryptojacking معالج الضحية لتعدين العملات."}},{"id":63,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"Gaining higher permissions than originally granted is?","ar":"الحصول على صلاحيات أعلى مما مُنح أصلاً هو؟"},"options":["Privilege escalation","Lateral host movement","Network enumeration","Internal host pivoting"],"answer":"Privilege escalation","explanation":{"en":"Privilege escalation raises an attacker's access level.","ar":"يرفع تصعيد الامتيازات مستوى وصول المهاجم."}},{"id":64,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"Moving from one compromised host to others on the network is?","ar":"الانتقال من مضيف مخترق إلى آخر في الشبكة هو؟"},"options":["Lateral movement","Privilege escalation","Reconnaissance","Exfiltration"],"answer":"Lateral movement","explanation":{"en":"Lateral movement spreads access across the network.","ar":"تنشر الحركة الجانبية الوصول عبر الشبكة."}},{"id":65,"category":"concepts","difficulty":"hard","codeSnippet":"","question":{"en":"Writing past the end of a memory buffer to corrupt memory is a?","ar":"الكتابة بعد نهاية مخزن في الذاكرة لإفسادها هو؟"},"options":["Buffer overflow","Race condition bug","SQL injection","Stored XSS flaw"],"answer":"Buffer overflow","explanation":{"en":"A buffer overflow overwrites adjacent memory, often enabling code execution.","ar":"يُفسد تجاوز سعة المخزن الذاكرة المجاورة وقد يسمح بتنفيذ شيفرة."}},{"id":66,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"Using ../ sequences to read files outside the web root is?","ar":"استخدام ../ لقراءة ملفات خارج جذر الموقع هو؟"},"options":["Directory (path) traversal","Reflected cross-site scripting","Cross-site request forgery","UI redress clickjacking"],"answer":"Directory (path) traversal","explanation":{"en":"Path traversal escapes the intended directory to read arbitrary files.","ar":"يتجاوز اجتياز المسارات المجلد المقصود لقراءة ملفات عشوائية."}},{"id":67,"category":"concepts","difficulty":"hard","codeSnippet":"","question":{"en":"Injecting operating-system commands through application input is?","ar":"حقن أوامر نظام التشغيل عبر مدخلات التطبيق هو؟"},"options":["Command injection","SQL query injection","Reflected XSS","Server-side SSRF"],"answer":"Command injection","explanation":{"en":"Command injection runs OS commands via unsanitized input.","ar":"ينفّذ حقن الأوامر أوامر النظام عبر مدخلات غير مُنقّاة."}},{"id":68,"category":"concepts","difficulty":"hard","codeSnippet":"","question":{"en":"Accessing another user's record by changing an id parameter is?","ar":"الوصول لسجل مستخدم آخر بتغيير معرّف هو؟"},"options":["IDOR","XSS","CSRF","SSRF"],"answer":"IDOR","explanation":{"en":"IDOR exposes objects directly by a guessable reference with no access check.","ar":"يكشف IDOR الكائنات عبر معرّف يمكن تخمينه دون تحقق من الصلاحية."}},{"id":69,"category":"concepts","difficulty":"hard","codeSnippet":"","question":{"en":"Forcing a server to make requests to internal resources is?","ar":"إجبار الخادم على إرسال طلبات لموارد داخلية هو؟"},"options":["SSRF","CSRF","XSS","RCE"],"answer":"SSRF","explanation":{"en":"SSRF makes the server fetch attacker-chosen (often internal) URLs.","ar":"يجعل SSRF الخادم يجلب روابط يحددها المهاجم (غالباً داخلية)."}},{"id":70,"category":"concepts","difficulty":"easy","codeSnippet":"","question":{"en":"The C-I-A triad stands for?","ar":"ماذا يعني ثالوث C-I-A؟"},"options":["Confidentiality, Integrity, Availability","Control, Identity, Access","Cipher, Integrity, Auth","Confidentiality, Identity, Audit"],"answer":"Confidentiality, Integrity, Availability","explanation":{"en":"The CIA triad is the core model of information security.","ar":"ثالوث CIA هو النموذج الأساسي لأمن المعلومات."}},{"id":71,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"Adding random data to a password before hashing is called?","ar":"إضافة بيانات عشوائية لكلمة المرور قبل التجزئة تُسمى؟"},"options":["Salting","Encoding","Encrypting","Compressing"],"answer":"Salting","explanation":{"en":"A salt makes identical passwords hash differently, defeating rainbow tables.","ar":"يجعل التمليح كلمات المرور المتطابقة تُجزّأ مختلفة، ويُبطل جداول قوس قزح."}},{"id":72,"category":"concepts","difficulty":"hard","codeSnippet":"","question":{"en":"Which uses a public/private key pair?","ar":"أيّها يستخدم زوج مفاتيح عام/خاص؟"},"options":["Asymmetric encryption (RSA)","Symmetric encryption (AES)","Hashing (SHA-256)","Base64 encoding"],"answer":"Asymmetric encryption (RSA)","explanation":{"en":"Asymmetric crypto (e.g. RSA) uses a public and a private key.","ar":"يستخدم التشفير غير المتماثل (مثل RSA) مفتاحاً عاماً وآخر خاصاً."}},{"id":73,"category":"concepts","difficulty":"easy","codeSnippet":"","question":{"en":"Which port does HTTPS use by default?","ar":"أي منفذ يستخدمه HTTPS افتراضياً؟"},"options":["443","80","22","3389"],"answer":"443","explanation":{"en":"HTTPS uses TCP port 443.","ar":"يستخدم HTTPS المنفذ 443."}},{"id":74,"category":"concepts","difficulty":"easy","codeSnippet":"","question":{"en":"Which port does SSH use by default?","ar":"أي منفذ يستخدمه SSH افتراضياً؟"},"options":["22","23","21","25"],"answer":"22","explanation":{"en":"SSH listens on TCP port 22.","ar":"يستمع SSH على المنفذ 22."}},{"id":75,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"Which port does RDP use by default?","ar":"أي منفذ يستخدمه RDP افتراضياً؟"},"options":["3389","3306","5900","8080"],"answer":"3389","explanation":{"en":"Remote Desktop (RDP) uses TCP port 3389.","ar":"يستخدم سطح المكتب البعيد RDP المنفذ 3389."}},{"id":76,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"Which port does DNS primarily use?","ar":"أي منفذ يستخدمه DNS أساساً؟"},"options":["53","80","443","123"],"answer":"53","explanation":{"en":"DNS primarily uses port 53 (UDP/TCP).","ar":"يستخدم DNS المنفذ 53 أساساً."}},{"id":77,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"SMB (exploited by EternalBlue) commonly runs on which port?","ar":"على أي منفذ يعمل SMB (الذي استغلّه EternalBlue) عادةً؟"},"options":["445","21","110","389"],"answer":"445","explanation":{"en":"Modern SMB runs on TCP port 445.","ar":"يعمل SMB الحديث على المنفذ 445."}},{"id":78,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"An IPS differs from an IDS because it?","ar":"كيف يختلف IPS عن IDS؟"},"options":["Actively blocks/prevents threats","Only logs the passing network traffic","Encrypts all of the network traffic","Stores periodic system backups"],"answer":"Actively blocks/prevents threats","explanation":{"en":"An IDS only detects/alerts; an IPS can block traffic inline.","ar":"يكتشف IDS وينبّه فقط، بينما يستطيع IPS حظر الحركة."}},{"id":79,"category":"tools","difficulty":"easy","codeSnippet":"","question":{"en":"A decoy system designed to lure and study attackers is a?","ar":"النظام الفخّ المصمّم لجذب المهاجمين ودراستهم هو؟"},"options":["Honeypot","Firewall","Sandbox","Proxy"],"answer":"Honeypot","explanation":{"en":"A honeypot is a decoy that attracts and observes attackers.","ar":"Honeypot نظام خداع يجذب المهاجمين ويراقبهم."}},{"id":80,"category":"nmap","difficulty":"medium","codeSnippet":"nmap -p- 10.0.0.1","question":{"en":"What does the -p- flag scan?","ar":"ماذا يفحص الخيار -p-؟"},"options":["All 65535 TCP ports","Only the top 100 ports","UDP ports only","Just port 80"],"answer":"All 65535 TCP ports","explanation":{"en":"-p- tells Nmap to scan every TCP port from 1 to 65535.","ar":"يطلب -p- من Nmap فحص كل منافذ TCP من 1 إلى 65535."}},{"id":81,"category":"nmap","difficulty":"medium","codeSnippet":"nmap -sn 192.168.1.0/24","question":{"en":"What does the -sn option do?","ar":"ماذا يفعل الخيار -sn؟"},"options":["Host discovery without a port scan","A full SYN port scan","Service version detection","An aggressive OS scan"],"answer":"Host discovery without a port scan","explanation":{"en":"-sn performs a ping sweep to find live hosts and skips port scanning.","ar":"ينفّذ -sn مسحاً بالـ ping لاكتشاف المضيفات الحيّة دون فحص المنافذ."}},{"id":82,"category":"tools","difficulty":"easy","codeSnippet":"","question":{"en":"Which tool captures and inspects network packets?","ar":"أي أداة تلتقط وتحلّل حزم الشبكة؟"},"options":["Wireshark","Hydra","Nikto","John the Ripper"],"answer":"Wireshark","explanation":{"en":"Wireshark is the standard packet capture and protocol analysis tool.","ar":"Wireshark هي الأداة المعيارية لالتقاط الحزم وتحليل البروتوكولات."}},{"id":83,"category":"tools","difficulty":"medium","codeSnippet":"hydra -l admin -P rockyou.txt ssh://10.0.0.5","question":{"en":"What is hydra doing in this command?","ar":"ماذا تفعل hydra في هذا الأمر؟"},"options":["Brute-forcing the SSH login","Scanning for open ports","Sniffing SSH traffic","Exploiting a buffer overflow"],"answer":"Brute-forcing the SSH login","explanation":{"en":"hydra tries passwords from rockyou.txt against the SSH service for user admin.","ar":"تجرّب hydra كلمات مرور من rockyou.txt ضد خدمة SSH للمستخدم admin."}},{"id":84,"category":"concepts","difficulty":"easy","codeSnippet":"","question":{"en":"What does the CIA triad stand for in security?","ar":"ماذا يعني ثالوث CIA في الأمن؟"},"options":["Confidentiality, Integrity, Availability","Control, Identity, Access","Cipher, Integrity, Authentication","Confidentiality, Identity, Auditing"],"answer":"Confidentiality, Integrity, Availability","explanation":{"en":"The CIA triad — Confidentiality, Integrity, Availability — is the core model of information security.","ar":"ثالوث CIA — السرية والسلامة والتوافر — هو النموذج الأساسي لأمن المعلومات."}},{"id":85,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"What is a zero-day vulnerability?","ar":"ما هي ثغرة اليوم صفر (zero-day)؟"},"options":["A flaw unknown to the vendor with no patch yet","A bug the vendor already fixed in the latest patch","An expired server TLS certificate","A weak, guessable default password"],"answer":"A flaw unknown to the vendor with no patch yet","explanation":{"en":"A zero-day is a vulnerability unknown to the vendor, so no patch exists when it is exploited.","ar":"ثغرة اليوم صفر غير معروفة للمطوّر، فلا يوجد تصحيح لها وقت استغلالها."}},{"id":86,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"Why is a salt added when hashing passwords?","ar":"لماذا يُضاف salt عند تجزئة كلمات المرور؟"},"options":["To defeat precomputed rainbow-table attacks","To let the password be decrypted again later","To compress the resulting stored hash","To make the hashing algorithm run faster"],"answer":"To defeat precomputed rainbow-table attacks","explanation":{"en":"A unique random salt makes identical passwords hash differently, defeating rainbow tables.","ar":"يجعل الـ salt العشوائي كلمات المرور المتطابقة تُجزّأ بشكل مختلف، ما يبطل جداول rainbow."}},{"id":87,"category":"malware","difficulty":"medium","codeSnippet":"","question":{"en":"What distinguishes a worm from a virus?","ar":"ما الذي يميّز الدودة عن الفيروس؟"},"options":["A worm self-replicates across networks without a host file","A worm must attach to a host file and needs a user to run it","A worm can only infect the disk's boot sectors","A worm is unable to spread over any network"],"answer":"A worm self-replicates across networks without a host file","explanation":{"en":"Worms propagate on their own across networks; viruses attach to and need a host file.","ar":"تنتشر الديدان ذاتياً عبر الشبكات، بينما يلتصق الفيروس بملف مضيف ويحتاجه."}},{"id":88,"category":"malware","difficulty":"medium","codeSnippet":"","question":{"en":"What is the primary goal of ransomware?","ar":"ما الهدف الأساسي لبرمجيات الفدية؟"},"options":["Encrypt files and demand payment to decrypt them","Silently mine cryptocurrency using the victim's CPU","Log only the victim's keystrokes to a file","Quietly open a remote backdoor for later access"],"answer":"Encrypt files and demand payment to decrypt them","explanation":{"en":"Ransomware encrypts the victim’s data and demands payment for the decryption key.","ar":"تشفّر برمجيات الفدية بيانات الضحية وتطلب فدية مقابل مفتاح فك التشفير."}},{"id":89,"category":"metasploit","difficulty":"medium","codeSnippet":"use exploit/windows/smb/ms17_010_eternalblue","question":{"en":"Which vulnerability does this Metasploit module exploit?","ar":"أي ثغرة تستغلها وحدة Metasploit هذه؟"},"options":["EternalBlue (SMBv1)","Heartbleed (OpenSSL)","Shellshock (Bash)","Log4Shell (Log4j)"],"answer":"EternalBlue (SMBv1)","explanation":{"en":"ms17_010 is the EternalBlue exploit against the SMBv1 protocol.","ar":"ms17_010 هي ثغرة EternalBlue ضد بروتوكول SMBv1."}},{"id":90,"category":"metasploit","difficulty":"easy","codeSnippet":"msfconsole","question":{"en":"What does msfconsole start?","ar":"ماذا يشغّل msfconsole؟"},"options":["The Metasploit Framework console","A live network packet sniffer tool","A recursive DNS resolver server","An encrypted local password vault"],"answer":"The Metasploit Framework console","explanation":{"en":"msfconsole is the main command-line interface to the Metasploit Framework.","ar":"msfconsole هي الواجهة الرئيسية لسطر أوامر إطار Metasploit."}},{"id":91,"category":"concepts","difficulty":"hard","codeSnippet":"","question":{"en":"In TLS, what is the role of a Certificate Authority (CA)?","ar":"في TLS، ما دور سلطة الشهادات (CA)؟"},"options":["It signs certificates to vouch for a server’s public key","It encrypts all of the application data exchanged over the link","It securely stores every user's login password","It hands out IP addresses to hosts on the network"],"answer":"It signs certificates to vouch for a server’s public key","explanation":{"en":"A CA digitally signs a server’s certificate, letting clients trust its public key.","ar":"توقّع سلطة الشهادات شهادة الخادم رقمياً ليثق العملاء بمفتاحه العام."}},{"id":92,"category":"tools","difficulty":"medium","codeSnippet":"john --wordlist=rockyou.txt hashes.txt","question":{"en":"What is John the Ripper doing here?","ar":"ماذا تفعل John the Ripper هنا؟"},"options":["Cracking password hashes using a wordlist","Scanning a host for known vulnerabilities","Capturing packets off the local network","Encrypting the captured hashes file safely"],"answer":"Cracking password hashes using a wordlist","explanation":{"en":"John tries each word in rockyou.txt against the hashes to recover passwords.","ar":"تجرّب John كل كلمة في rockyou.txt ضد التجزئات لاستعادة كلمات المرور."}},{"id":93,"category":"concepts","difficulty":"easy","codeSnippet":"","question":{"en":"What do the three letters in the CIA triad stand for?","ar":"ماذا تعني الأحرف الثلاثة في ثالوث CIA؟"},"options":["Confidentiality, Integrity, Availability","Control, Identity, Access","Cipher, Integrity, Auth","Confidentiality, Identity, Audit"],"answer":"Confidentiality, Integrity, Availability","explanation":{"en":"The CIA triad is the core model of information security.","ar":"ثالوث CIA هو النموذج الأساسي لأمن المعلومات."}},{"id":94,"category":"web","difficulty":"easy","codeSnippet":"' OR '1'='1","question":{"en":"This input in a login form is a classic example of which attack?","ar":"هذا الإدخال في نموذج تسجيل الدخول مثال كلاسيكي لأي هجوم؟"},"options":["SQL injection","Cross-site scripting","Buffer overflow","Phishing"],"answer":"SQL injection","explanation":{"en":"It manipulates the SQL query to always evaluate true.","ar":"يتلاعب باستعلام SQL ليصبح صحيحًا دائمًا."}},{"id":95,"category":"web","difficulty":"medium","codeSnippet":"<script>alert(1)<\/script>","question":{"en":"Storing this in a comment field to run in the browsers of other users is which attack?","ar":"تخزين هذا في حقل تعليق ليُنفَّذ في متصفحات آخرين هو أي هجوم؟"},"options":["Cross-site scripting (XSS)","SQL database injection attack","Cross-site request forgery","UI redress clickjacking"],"answer":"Cross-site scripting (XSS)","explanation":{"en":"Stored XSS injects script that runs for other visitors.","ar":"XSS المخزّن يحقن سكربتًا يعمل لدى زوار آخرين."}},{"id":96,"category":"tools","difficulty":"easy","codeSnippet":"hashcat -m 0 hash.txt words.txt","question":{"en":"The -m 0 mode tells hashcat the hashes are which type?","ar":"الوضع m 0- يخبر hashcat أن التجزئات من أي نوع؟"},"options":["MD5","SHA-256","bcrypt","NTLM"],"answer":"MD5","explanation":{"en":"Mode 0 in hashcat targets raw MD5 hashes.","ar":"الوضع 0 في hashcat يستهدف تجزئات MD5 الخام."}},{"id":97,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"Adding a random salt to passwords before hashing mainly defeats what?","ar":"إضافة ملح عشوائي لكلمات المرور قبل التجزئة يُبطل ماذا أساسًا؟"},"options":["Precomputed rainbow-table attacks","Man-in-the-middle interception attacks","Targeted credential phishing emails","Volumetric DDoS traffic floods"],"answer":"Precomputed rainbow-table attacks","explanation":{"en":"Unique salts make precomputed hash tables useless.","ar":"الأملاح الفريدة تجعل جداول التجزئة المحسوبة مسبقًا عديمة الفائدة."}},{"id":98,"category":"nmap","difficulty":"medium","codeSnippet":"nmap -p- 10.0.0.1","question":{"en":"What does the -p- flag scan?","ar":"ماذا يفحص الخيار p-؟"},"options":["All 65535 TCP ports","Only the top 100 ports","UDP ports only","The default 1000 ports"],"answer":"All 65535 TCP ports","explanation":{"en":"-p- expands the scan to every TCP port.","ar":"p- يوسّع الفحص ليشمل كل منافذ TCP."}},{"id":99,"category":"metasploit","difficulty":"easy","codeSnippet":"set RHOSTS 10.0.0.5","question":{"en":"In Metasploit, what does RHOSTS specify?","ar":"في Metasploit ماذا يحدّد RHOSTS؟"},"options":["The target host(s)","The local listener IP","The payload","The exploit name"],"answer":"The target host(s)","explanation":{"en":"RHOSTS sets the remote target address(es).","ar":"RHOSTS يضبط عنوان الهدف البعيد."}},{"id":100,"category":"tools","difficulty":"medium","codeSnippet":"hydra -l admin -P pass.txt ssh://10.0.0.1","question":{"en":"What is this command doing?","ar":"ماذا يفعل هذا الأمر؟"},"options":["Brute-forcing an SSH login","Scanning open ports","Sniffing traffic","Encrypting a file"],"answer":"Brute-forcing an SSH login","explanation":{"en":"Hydra tries each password against the SSH service.","ar":"تجرّب Hydra كل كلمة مرور ضد خدمة SSH."}},{"id":101,"category":"concepts","difficulty":"easy","codeSnippet":"","question":{"en":"What best describes phishing?","ar":"ما الوصف الأدق للتصيّد الاحتيالي؟"},"options":["Tricking users into revealing credentials","Overloading a server with junk traffic","Cracking a stored password hash offline","Scanning a whole network for open ports"],"answer":"Tricking users into revealing credentials","explanation":{"en":"Phishing uses deception to steal sensitive info.","ar":"التصيّد يستخدم الخداع لسرقة معلومات حساسة."}},{"id":102,"category":"web","difficulty":"medium","codeSnippet":"GET /files?name=../../etc/passwd","question":{"en":"This request is attempting which attack?","ar":"هذا الطلب يحاول أي هجوم؟"},"options":["Path (directory) traversal","SQL database injection","Reflected cross-site scripting","Session token hijacking"],"answer":"Path (directory) traversal","explanation":{"en":"../ sequences escape the intended directory.","ar":"تسلسلات ../ تتجاوز المجلد المقصود."}},{"id":103,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"Symmetric encryption is defined by what property?","ar":"ما الخاصية التي تُعرّف التشفير المتماثل؟"},"options":["The same key encrypts and decrypts","A public/private key pair is used","It only works in one direction","It needs no encryption key at all"],"answer":"The same key encrypts and decrypts","explanation":{"en":"Symmetric ciphers share one secret key.","ar":"الشيفرات المتماثلة تتشارك مفتاحًا سريًا واحدًا."}},{"id":104,"category":"tools","difficulty":"easy","codeSnippet":"","question":{"en":"Wireshark is primarily used to do what?","ar":"لأي غرض يُستخدم Wireshark أساسًا؟"},"options":["Capture and analyze network packets","Crack stored password hashes offline","Exploit vulnerable network services","Fuzz web application input fields"],"answer":"Capture and analyze network packets","explanation":{"en":"Wireshark is a packet capture and analysis tool.","ar":"Wireshark أداة لالتقاط وتحليل الحزم."}},{"id":105,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"What is a zero-day vulnerability?","ar":"ما ثغرة اليوم صفر؟"},"options":["A flaw with no available patch yet","A bug that the vendor patched long ago","A weak and guessable password","A credential-phishing email lure"],"answer":"A flaw with no available patch yet","explanation":{"en":"Zero-days are unknown to the vendor and unpatched.","ar":"ثغرات اليوم صفر مجهولة للمزوّد وبلا رقعة."}},{"id":106,"category":"malware","difficulty":"easy","codeSnippet":"","question":{"en":"What does ransomware typically do?","ar":"ماذا تفعل برامج الفدية عادةً؟"},"options":["Encrypt files and demand payment","Log keystrokes silently","Mine cryptocurrency","Spread via USB only"],"answer":"Encrypt files and demand payment","explanation":{"en":"Ransomware encrypts data and extorts a ransom.","ar":"تشفّر برامج الفدية البيانات وتبتزّ فدية."}},{"id":107,"category":"concepts","difficulty":"easy","codeSnippet":"","question":{"en":"What does two-factor authentication add?","ar":"ماذا تضيف المصادقة الثنائية؟"},"options":["A second, independent verification factor","A single much longer and more complex password","An extra perimeter firewall rule","A scheduled full antivirus scan"],"answer":"A second, independent verification factor","explanation":{"en":"2FA requires something you have in addition to a password.","ar":"تتطلب 2FA شيئًا تملكه إضافة لكلمة المرور."}},{"id":108,"category":"web","difficulty":"easy","codeSnippet":"","question":{"en":"Which port does HTTPS use by default?","ar":"أي منفذ يستخدمه HTTPS افتراضيًا؟"},"options":["443","80","22","8080"],"answer":"443","explanation":{"en":"HTTPS runs over TLS on TCP port 443.","ar":"يعمل HTTPS عبر TLS على المنفذ 443."}},{"id":109,"category":"tools","difficulty":"medium","codeSnippet":"openssl req -new -x509 -days 365 -key key.pem","question":{"en":"What does this openssl command create?","ar":"ماذا ينشئ أمر openssl هذا؟"},"options":["A self-signed certificate","A salted password hash value","A new SSH key pair","A host firewall rule"],"answer":"A self-signed certificate","explanation":{"en":"-x509 produces a self-signed X.509 certificate.","ar":"x509- ينتج شهادة X.509 موقّعة ذاتيًا."}},{"id":110,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"Unlike encryption, hashing is primarily used for what?","ar":"بخلاف التشفير، لأي غرض تُستخدم التجزئة أساسًا؟"},"options":["One-way integrity verification","Reversible two-way data concealment","Secure session key exchange","Encrypted traffic tunneling"],"answer":"One-way integrity verification","explanation":{"en":"Hashes are one-way and verify data integrity.","ar":"التجزئات أحادية الاتجاه وتتحقق من سلامة البيانات."}},{"id":111,"category":"nmap","difficulty":"easy","codeSnippet":"nmap -sV 10.0.0.5","question":{"en":"What does the -sV flag add to this scan?","ar":"ماذا تضيف الراية -sV إلى هذا الفحص؟"},"options":["Service and version detection","A ping sweep of the hosts only","An OS-fingerprint-only scan","UDP datagram port scanning only"],"answer":"Service and version detection","explanation":{"en":"-sV probes open ports to identify the service and its version.","ar":"تستكشف -sV المنافذ المفتوحة لتحديد الخدمة وإصدارها."}},{"id":112,"category":"nmap","difficulty":"medium","codeSnippet":"nmap -p- 10.0.0.5","question":{"en":"How many TCP ports does -p- scan?","ar":"كم منفذ TCP يفحصه الخيار -p-؟"},"options":["All 65535 ports","The top 1000 ports","Only port 80","Only privileged ports"],"answer":"All 65535 ports","explanation":{"en":"-p- is shorthand for the full 1-65535 TCP range.","ar":"الخيار -p- اختصار للمدى الكامل 1-65535 من منافذ TCP."}},{"id":113,"category":"nmap","difficulty":"medium","codeSnippet":"nmap -sn 192.168.1.0/24","question":{"en":"What is this command doing?","ar":"ماذا يفعل هذا الأمر؟"},"options":["Discovering live hosts without scanning ports","Scanning every single port on every host","Fingerprinting the operating systems of all hosts","Brute-forcing remote SSH login credentials"],"answer":"Discovering live hosts without scanning ports","explanation":{"en":"-sn is a host-discovery (ping) sweep with the port scan disabled.","ar":"الخيار -sn مسح لاكتشاف المضيفين مع تعطيل فحص المنافذ."}},{"id":114,"category":"nmap","difficulty":"medium","codeSnippet":"nmap -O 10.0.0.5","question":{"en":"What does -O attempt?","ar":"ماذا يحاول الخيار -O؟"},"options":["Operating system fingerprinting","Opening a reverse shell","Writing output to a file","Scanning only open ports"],"answer":"Operating system fingerprinting","explanation":{"en":"-O guesses the OS from TCP/IP stack behaviour.","ar":"يخمّن -O نظام التشغيل من سلوك حزمة TCP/IP."}},{"id":115,"category":"tools","difficulty":"medium","codeSnippet":"hydra -l admin -P rockyou.txt ssh://10.0.0.5","question":{"en":"What is this command doing?","ar":"ماذا يفعل هذا الأمر؟"},"options":["Brute-forcing SSH credentials from a wordlist","Encrypting an SSH private key file safely","Capturing and decrypting packets on the local network","Scanning the target host for open TCP ports"],"answer":"Brute-forcing SSH credentials from a wordlist","explanation":{"en":"hydra tries each password in the list against the SSH service.","ar":"يجرّب hydra كل كلمة مرور في القائمة على خدمة SSH."}},{"id":116,"category":"tools","difficulty":"medium","codeSnippet":"john --wordlist=rockyou.txt hashes.txt","question":{"en":"What does John the Ripper do here?","ar":"ماذا يفعل John the Ripper هنا؟"},"options":["Cracks password hashes offline","Sniffs credentials off the wire","Exploits a remote service","Generates a TLS certificate"],"answer":"Cracks password hashes offline","explanation":{"en":"It hashes each candidate word and compares it to the stored hashes.","ar":"يجزّئ كل كلمة مرشّحة ويقارنها بالتجزئات المخزّنة."}},{"id":117,"category":"tools","difficulty":"medium","codeSnippet":"tcpdump -i eth0 port 80 -w capture.pcap","question":{"en":"What is captured here?","ar":"ما الذي يُلتقط هنا؟"},"options":["Port 80 traffic on eth0, saved to a file","All traffic seen on every network interface","Only the outgoing DNS query packets now","The system kernel log messages only"],"answer":"Port 80 traffic on eth0, saved to a file","explanation":{"en":"-i picks the interface, the filter limits it to port 80, -w writes a pcap.","ar":"يحدّد -i الواجهة، والمُرشِّح يقصره على المنفذ 80، و-w يكتب ملف pcap."}},{"id":118,"category":"tools","difficulty":"hard","codeSnippet":"openssl s_client -connect example.com:443","question":{"en":"What does this command inspect?","ar":"ماذا يفحص هذا الأمر؟"},"options":["The TLS handshake and certificate chain","The server's currently open UDP listening ports","The server's password-policy rules","The domain's full DNS zone records"],"answer":"The TLS handshake and certificate chain","explanation":{"en":"s_client opens a TLS connection and prints the negotiated certificate chain.","ar":"يفتح s_client اتصال TLS ويطبع سلسلة الشهادات المتفاوض عليها."}},{"id":119,"category":"web","difficulty":"easy","codeSnippet":"' OR '1'='1' --","question":{"en":"Which attack does this payload represent?","ar":"أي هجوم يمثّله هذا الحمل؟"},"options":["SQL injection","Cross-site scripting","Path traversal","CSRF"],"answer":"SQL injection","explanation":{"en":"It closes the quote and appends an always-true condition to the query.","ar":"يغلق علامة التنصيص ويضيف شرطًا صحيحًا دائمًا إلى الاستعلام."}},{"id":120,"category":"web","difficulty":"easy","codeSnippet":"<script>alert(1)<\/script>","question":{"en":"Which vulnerability does this test for?","ar":"عن أي ثغرة يختبر هذا؟"},"options":["Cross-site scripting (XSS)","SQL database injection attack","A stack buffer overflow","DNS cache spoofing attack"],"answer":"Cross-site scripting (XSS)","explanation":{"en":"Unescaped output lets attacker script run in the victim's browser.","ar":"الإخراج غير المُهرَّب يسمح بتشغيل سكربت المهاجم في متصفح الضحية."}},{"id":121,"category":"web","difficulty":"medium","codeSnippet":"GET /download?file=../../etc/passwd","question":{"en":"Which attack is this?","ar":"ما هذا الهجوم؟"},"options":["Path traversal","Open redirect","Clickjacking","Session fixation"],"answer":"Path traversal","explanation":{"en":"../ sequences escape the intended directory to read arbitrary files.","ar":"تتيح تسلسلات ../ الخروج من المجلد المقصود لقراءة ملفات عشوائية."}},{"id":122,"category":"web","difficulty":"medium","codeSnippet":"","question":{"en":"Which response header forces browsers to use HTTPS only?","ar":"أي ترويسة استجابة تُلزم المتصفح باستخدام HTTPS فقط؟"},"options":["Strict-Transport-Security","X-Frame-Options","Content-Encoding","Accept-Language"],"answer":"Strict-Transport-Security","explanation":{"en":"HSTS tells the browser to refuse plaintext HTTP for the domain.","ar":"تخبر HSTS المتصفح برفض HTTP غير المشفّر لهذا النطاق."}},{"id":123,"category":"web","difficulty":"medium","codeSnippet":"","question":{"en":"What does a CSRF attack abuse?","ar":"ما الذي يستغله هجوم CSRF؟"},"options":["The victim's already-authenticated session","A weak and outdated password-hashing algorithm","An open, unfiltered inbound TCP port","A missing index on a database table"],"answer":"The victim's already-authenticated session","explanation":{"en":"The browser attaches the victim's cookies to the attacker's forged request.","ar":"يُرفق المتصفح كوكيز الضحية بالطلب المزيّف الذي أعدّه المهاجم."}},{"id":124,"category":"concepts","difficulty":"easy","codeSnippet":"","question":{"en":"What is the principle of least privilege?","ar":"ما مبدأ الحد الأدنى من الصلاحيات؟"},"options":["Grant only the access a task requires","Give admins access to everything","Encrypt every file on disk","Rotate passwords every day"],"answer":"Grant only the access a task requires","explanation":{"en":"Least privilege limits the damage a compromised account can do.","ar":"يحدّ المبدأ من الضرر الذي يسببه حساب مُخترق."}},{"id":125,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"Which of these is asymmetric encryption?","ar":"أي من هذه تشفير غير متماثل؟"},"options":["RSA","AES","SHA-256","HMAC"],"answer":"RSA","explanation":{"en":"RSA uses a public/private key pair; AES is symmetric and SHA-256 is a hash.","ar":"يستخدم RSA زوج مفاتيح عام وخاص، أما AES متماثل وSHA-256 دالة تجزئة."}},{"id":126,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"What does salting a password hash prevent?","ar":"ماذا يمنع إضافة مِلح لتجزئة كلمة المرور؟"},"options":["Precomputed rainbow-table lookups","All brute-force guessing attempts","Passive network traffic eavesdropping","SQL database injection attacks"],"answer":"Precomputed rainbow-table lookups","explanation":{"en":"A unique salt per user makes precomputed hash tables useless.","ar":"المِلح الفريد لكل مستخدم يجعل جداول التجزئة المحسوبة مسبقًا بلا فائدة."}},{"id":127,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"What is privilege escalation?","ar":"ما تصعيد الصلاحيات؟"},"options":["Gaining permissions beyond those granted","Resetting a forgotten password","Encrypting traffic end to end","Load balancing between servers"],"answer":"Gaining permissions beyond those granted","explanation":{"en":"An attacker moves from a limited account to an administrative one.","ar":"ينتقل المهاجم من حساب محدود إلى حساب إداري."}},{"id":128,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"What does a web application firewall do?","ar":"ماذا يفعل جدار حماية تطبيقات الويب؟"},"options":["Inspects and filters malicious HTTP requests","Encrypts the database at rest","Assigns IP addresses to clients","Compiles application code"],"answer":"Inspects and filters malicious HTTP requests","explanation":{"en":"A WAF sits in front of the app and blocks known attack patterns.","ar":"يقف WAF أمام التطبيق ويحجب أنماط الهجوم المعروفة."}},{"id":129,"category":"malware","difficulty":"easy","codeSnippet":"","question":{"en":"What defines ransomware?","ar":"ما الذي يُعرِّف برامج الفدية؟"},"options":["It encrypts data and demands payment","It silently mines cryptocurrency","It only spreads over USB drives","It replaces the login screen"],"answer":"It encrypts data and demands payment","explanation":{"en":"Ransomware denies access to your own files until a ransom is paid.","ar":"تمنع برامج الفدية الوصول إلى ملفاتك حتى تُدفع الفدية."}},{"id":130,"category":"malware","difficulty":"medium","codeSnippet":"","question":{"en":"What is a rootkit's main goal?","ar":"ما الهدف الرئيسي للـ rootkit؟"},"options":["Hide its presence while keeping privileged access","Encrypt every one of the user's documents for ransom","Flood a chosen target host with junk traffic","Harvest email addresses from the host only"],"answer":"Hide its presence while keeping privileged access","explanation":{"en":"Rootkits tamper with the OS so tools no longer report them.","ar":"تتلاعب الـ rootkits بنظام التشغيل حتى لا تُظهرها الأدوات."}},{"id":131,"category":"metasploit","difficulty":"medium","codeSnippet":"use exploit/windows/smb/ms17_010_eternalblue","question":{"en":"What does this line do in msfconsole?","ar":"ماذا يفعل هذا السطر في msfconsole؟"},"options":["Selects an SMB exploit module","Starts a packet capture","Scans a subnet for hosts","Generates a wordlist"],"answer":"Selects an SMB exploit module","explanation":{"en":"\`use\` loads a module so its options can be configured and run.","ar":"يحمّل \`use\` وحدة لتهيئة خياراتها وتشغيلها."}},{"id":132,"category":"metasploit","difficulty":"medium","codeSnippet":"set LHOST 10.0.0.2","question":{"en":"What is LHOST?","ar":"ما هو LHOST؟"},"options":["The attacker address the payload connects back to","The victim machine's public-facing IP address here","The exploit's remote target port number","The file name of the generated payload"],"answer":"The attacker address the payload connects back to","explanation":{"en":"LHOST is the local listener address for a reverse connection.","ar":"LHOST هو عنوان المستقبل المحلي للاتصال العكسي."}},{"id":133,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"What is the principle of least privilege?","ar":"ما مبدأ الحدّ الأدنى من الصلاحيات؟"},"options":["Grant only the access that is needed","Give admins access to everything","Share one account across a team","Disable all logging by default"],"answer":"Grant only the access that is needed","explanation":{"en":"Each user or process gets the minimum rights required, limiting damage.","ar":"كل مستخدم أو عملية يأخذ أقل الصلاحيات اللازمة، فيقلّ الضرر."}},{"id":134,"category":"defense","difficulty":"easy","codeSnippet":"","question":{"en":"What does a firewall's default-deny rule do?","ar":"ماذا تفعل قاعدة \\"المنع الافتراضي\\" في الجدار الناري؟"},"options":["Block anything not explicitly allowed","Allow anything not explicitly blocked","Log the traffic without filtering it","Encrypt every packet it forwards on"],"answer":"Block anything not explicitly allowed","explanation":{"en":"A default-deny stance only permits traffic that matches an allow rule.","ar":"المنع الافتراضي يسمح فقط بحركة تطابق قاعدة سماح."}},{"id":135,"category":"attacks","difficulty":"medium","codeSnippet":"","question":{"en":"What is a brute-force attack?","ar":"ما هجوم القوة الغاشمة؟"},"options":["Trying many guesses until one works","Tricking a user with a fake email","Intercepting traffic between hosts","Overloading a server with requests"],"answer":"Trying many guesses until one works","explanation":{"en":"It systematically tries passwords or keys until it finds a valid one.","ar":"يجرّب كلمات المرور أو المفاتيح بشكل منهجي حتى يجد صحيحًا."}},{"id":136,"category":"crypto","difficulty":"medium","codeSnippet":"","question":{"en":"What does hashing a password store?","ar":"ماذا يخزّن تجزئة كلمة المرور؟"},"options":["A one-way digest, not the password","The password encrypted with a key","The password in plain readable text","A shortened copy of the password"],"answer":"A one-way digest, not the password","explanation":{"en":"A good hash can't be reversed, so the original password isn't stored.","ar":"التجزئة الجيدة لا يمكن عكسها، فلا تُخزّن كلمة المرور الأصلية."}},{"id":137,"category":"attacks","difficulty":"hard","codeSnippet":"","question":{"en":"What is a supply-chain attack?","ar":"ما هجوم سلسلة التوريد؟"},"options":["Compromising a trusted dependency","Guessing a user's weak password","Flooding a target with junk traffic","Reading files outside the web root"],"answer":"Compromising a trusted dependency","explanation":{"en":"Attackers poison a library or update that many victims already trust.","ar":"يسمّم المهاجمون مكتبة أو تحديثًا يثق به كثير من الضحايا مسبقًا."}},{"id":138,"category":"auth","difficulty":"easy","codeSnippet":"","question":{"en":"What does two-factor authentication protect against?","ar":"ممّ تحمي المصادقة الثنائية؟"},"options":["A stolen password on its own","A slow internet connection now","A corrupted local backup file","An expired TLS certificate chain"],"answer":"A stolen password on its own","explanation":{"en":"Even with the password, an attacker still lacks the second factor.","ar":"حتى مع كلمة المرور، يبقى المهاجم بلا العامل الثاني."}},{"id":139,"category":"attacks","difficulty":"medium","codeSnippet":"","question":{"en":"What is phishing aimed at?","ar":"إلامَ يهدف التصيّد (phishing)؟"},"options":["Tricking people into leaking secrets","Cracking a password hash on a GPU","Scanning a subnet for live hosts","Escalating local user privileges"],"answer":"Tricking people into leaking secrets","explanation":{"en":"Phishing manipulates people, not machines, into revealing credentials.","ar":"يتلاعب التصيّد بالبشر لا بالأجهزة ليكشفوا بياناتهم."}},{"id":140,"category":"concepts","difficulty":"medium","codeSnippet":"","question":{"en":"What is a CVE identifier?","ar":"ما معرّف CVE؟"},"options":["A public id for a known vulnerability","A type of antivirus scan signature","A firewall rule numbering scheme","A password-strength score value out"],"answer":"A public id for a known vulnerability","explanation":{"en":"CVE ids give everyone a shared reference for a specific disclosed flaw.","ar":"تمنح معرّفات CVE الجميع مرجعًا موحّدًا لثغرة مُعلَنة محددة."}},{"id":141,"category":"attacks","difficulty":"hard","codeSnippet":"","question":{"en":"What is 'lateral movement'?","ar":"ما \\"الحركة الجانبية\\"؟"},"options":["Spreading to other hosts after entry","Gaining higher privileges on one host","Deleting logs to hide the activity","Encrypting files to demand a ransom"],"answer":"Spreading to other hosts after entry","explanation":{"en":"After a foothold, the attacker pivots across the network to more systems.","ar":"بعد موطئ القدم، ينتقل المهاجم عبر الشبكة إلى أنظمة أخرى."}},{"id":142,"category":"crypto","difficulty":"easy","codeSnippet":"","question":{"en":"What does encryption primarily protect?","ar":"ماذا تحمي التعمية (encryption) أساسًا؟"},"options":["The confidentiality of the data","The speed of the network link","The uptime of a single server","The size of the stored database"],"answer":"The confidentiality of the data","explanation":{"en":"Encryption keeps data unreadable to anyone without the key.","ar":"تُبقي التعمية البيانات غير مقروءة لمن لا يملك المفتاح."}},{"id":143,"category":"web","difficulty":"medium","codeSnippet":"\\"<script>alert(1)<\/script>\\" stored and shown","question":{"en":"Which vulnerability does this demonstrate?","ar":"أي ثغرة يوضّحها هذا؟"},"options":["Cross-site scripting","SQL injection flaw","Open redirect issue","Weak password reuse"],"answer":"Cross-site scripting","explanation":{"en":"Rendering unescaped user input lets injected script run in the browser (XSS).","ar":"عرض مدخلات المستخدم دون تهريب يسمح بتنفيذ سكربت محقون في المتصفح (XSS)."}},{"id":144,"category":"crypto","difficulty":"medium","codeSnippet":"store: bcrypt(password + salt)","question":{"en":"Why store a salted bcrypt hash?","ar":"لماذا نخزّن تجزئة bcrypt مملّحة؟"},"options":["Slow, unique per-user hashing","Reversible fast encryption","Plaintext for easy login","A shorter database column"],"answer":"Slow, unique per-user hashing","explanation":{"en":"bcrypt is deliberately slow and salted, resisting brute force and rainbow tables.","ar":"bcrypt بطيء ومملّح عمدًا فيقاوم التخمين وجداول قوس قزح."}},{"id":145,"category":"web","difficulty":"hard","codeSnippet":"query = \\"SELECT * FROM u WHERE id=\\" + input","question":{"en":"How is this best fixed?","ar":"ما أفضل إصلاح لهذا؟"},"options":["Use parameterized queries","Trust the client input","Hide the SQL errors","Rename the table columns"],"answer":"Use parameterized queries","explanation":{"en":"Prepared statements separate code from data, preventing SQL injection.","ar":"الاستعلامات المُعدّة تفصل الشيفرة عن البيانات فتمنع حقن SQL."}},{"id":146,"category":"auth","difficulty":"medium","codeSnippet":"// login asks password + phone code","question":{"en":"What security control is this?","ar":"أي ضابط أمني هذا؟"},"options":["Multi-factor authentication","Single sign-on only","Password rotation policy","Role based access lists"],"answer":"Multi-factor authentication","explanation":{"en":"Combining something you know and have is multi-factor authentication.","ar":"الجمع بين شيء تعرفه وشيء تملكه هو المصادقة متعددة العوامل."}},{"id":147,"category":"network","difficulty":"hard","codeSnippet":"// attacker relays traffic between two parties","question":{"en":"What attack is being described?","ar":"أي هجوم يُوصَف هنا؟"},"options":["A man-in-the-middle attack","A denial of service flood","A password spraying run","A privilege escalation bug"],"answer":"A man-in-the-middle attack","explanation":{"en":"Intercepting and relaying traffic between two ends is a man-in-the-middle attack.","ar":"اعتراض وتمرير الحركة بين طرفين هو هجوم الوسيط."}},{"id":148,"category":"web","difficulty":"medium","codeSnippet":"// form submits without an anti-forgery token","question":{"en":"Which attack does a missing token enable?","ar":"أي هجوم يتيحه غياب الرمز؟"},"options":["Cross-site request forgery","Buffer overflow crash","DNS cache poisoning","Clickjacking overlay only"],"answer":"Cross-site request forgery","explanation":{"en":"Without a CSRF token an attacker site can forge authenticated requests.","ar":"بدون رمز CSRF يمكن لموقع مهاجم تزوير طلبات مُصادَقة."}},{"id":149,"category":"principles","difficulty":"easy","codeSnippet":"// give each account only what it needs","question":{"en":"Which principle is this?","ar":"أي مبدأ هذا؟"},"options":["Least privilege access","Security through obscurity","Full trust by default","Shared admin accounts"],"answer":"Least privilege access","explanation":{"en":"Least privilege grants the minimum rights required, limiting damage.","ar":"أقل صلاحية تمنح الحد الأدنى من الحقوق فتحدّ من الضرر."}},{"id":150,"category":"crypto","difficulty":"hard","codeSnippet":"// same key encrypts and decrypts","question":{"en":"What type of encryption is this?","ar":"أي نوع تشفير هذا؟"},"options":["Symmetric key encryption","Asymmetric public keys","One-way hash function","Plaintext encoding only"],"answer":"Symmetric key encryption","explanation":{"en":"Symmetric ciphers like AES use one shared key for both directions.","ar":"الشفرات المتماثلة مثل AES تستخدم مفتاحًا مشتركًا للاتجاهين."}},{"id":151,"category":"malware","difficulty":"medium","codeSnippet":"// files encrypted, ransom note appears","question":{"en":"What malware category is this?","ar":"أي فئة برمجيات خبيثة هذه؟"},"options":["Ransomware","Adware popups","A keylogger","A rootkit"],"answer":"Ransomware","explanation":{"en":"Ransomware encrypts data and demands payment for the key.","ar":"برمجية الفدية تشفّر البيانات وتطلب دفعًا مقابل المفتاح."}},{"id":152,"category":"auth","difficulty":"hard","codeSnippet":"Authorization: Bearer eyJhbGci...","question":{"en":"What is this bearer token typically?","ar":"ما هذا الرمز (bearer) عادةً؟"},"options":["A signed JSON web token","A raw database password","A public TLS certificate","A one-time hardware pin"],"answer":"A signed JSON web token","explanation":{"en":"Bearer tokens are often JWTs whose signature the server verifies.","ar":"رموز الحامل غالبًا JWT يتحقق الخادم من توقيعها."}},{"id":153,"category":"social","difficulty":"easy","codeSnippet":"// email: 'verify your bank now' fake link","question":{"en":"This is an example of what?","ar":"هذا مثال على ماذا؟"},"options":["A phishing attempt","A firewall rule","A backup policy","A patch update"],"answer":"A phishing attempt","explanation":{"en":"Phishing tricks users into revealing credentials via fake messages.","ar":"التصيّد يخدع المستخدمين للكشف عن بياناتهم عبر رسائل مزيفة."}},{"id":154,"category":"network","difficulty":"medium","codeSnippet":"// huge traffic floods the site offline","question":{"en":"Which attack overwhelms a service with traffic?","ar":"أي هجوم يُغرق الخدمة بالحركة؟"},"options":["Distributed denial of service","Cross-site scripting","Privilege escalation","Certificate pinning"],"answer":"Distributed denial of service","explanation":{"en":"A DDoS floods a target from many sources to exhaust its resources.","ar":"هجوم DDoS يُغرق الهدف من مصادر كثيرة لاستنزاف موارده."}},{"id":155,"category":"web","difficulty":"hard","codeSnippet":"Set-Cookie: session=abc; HttpOnly; Secure","question":{"en":"What does the HttpOnly flag do?","ar":"ماذا يفعل الوسم HttpOnly؟"},"options":["Blocks JavaScript cookie access","Encrypts the whole response","Extends the cookie lifetime","Shares it across domains"],"answer":"Blocks JavaScript cookie access","explanation":{"en":"HttpOnly hides the cookie from document.cookie, mitigating XSS theft.","ar":"HttpOnly يخفي الكوكي عن document.cookie فيقلّل سرقتها عبر XSS."}},{"id":156,"category":"principles","difficulty":"medium","codeSnippet":"// firewall + MFA + backups + training","question":{"en":"What strategy layers many defenses?","ar":"أي استراتيجية تُراكم دفاعات متعددة؟"},"options":["Defense in depth","A single strong wall","Trust but never verify","Obscurity only design"],"answer":"Defense in depth","explanation":{"en":"Defense in depth uses overlapping controls so one failure isn't fatal.","ar":"الدفاع المتعمّق يستخدم ضوابط متداخلة فلا يكون فشل واحد قاتلًا."}},{"id":157,"category":"crypto","difficulty":"easy","codeSnippet":"sha256(file) == published_hash","question":{"en":"What does matching the hash verify?","ar":"ماذا تتحقق مطابقة التجزئة؟"},"options":["The file's integrity","The author's identity","The download speed","The file's price"],"answer":"The file's integrity","explanation":{"en":"A matching hash shows the file was not altered in transit.","ar":"تطابق التجزئة يدل على أن الملف لم يُعدَّل أثناء النقل."}}]`);export{e as default};
